<?php
namespace App\Services;
use App\Models\{Coupon,CouponUsage,Order,OrderItem,Product,ProductVariant}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class OrderService {
 public function create(array $d, $user=null):array { if(empty($d['items'])||!is_array($d['items']))throw ValidationException::withMessages(['items'=>['অর্ডারে কোনো পণ্য নেই।']]); return DB::transaction(function()use($d,$user){$subtotal=0;$server=[];foreach($d['items'] as $item){$qty=(int)($item['quantity']??0);if($qty<1||$qty>50)throw ValidationException::withMessages(['items'=>['Invalid product quantity']]);$pid=(string)($item['product_id']??'');$p=Product::where('is_active',true)->where(fn($q)=>$q->where('id',$pid)->orWhere('legacy_id',$pid))->lockForUpdate()->first();if(!$p)throw ValidationException::withMessages(['items'=>['Product not found: '.$pid]]);$variant=null;$price=(float)$p->price;$stock=(int)$p->stock_quantity;$label=isset($item['variant_label'])?trim((string)$item['variant_label']):null;if($label){$variant=ProductVariant::where('product_id',$p->id)->where('label',$label)->where('is_active',true)->lockForUpdate()->first();if($variant){$price=(float)$variant->price;$stock=$variant->stock_quantity;}elseif($label==='৫০০ গ্রাম')$price=round($price*.5,2);elseif($label==='২ কেজি')$price=round($price*2,2);elseif($label!=='১ কেজি')throw ValidationException::withMessages(['items'=>['Unknown product variant']]);}if($stock<$qty)throw ValidationException::withMessages(['items'=>['Insufficient stock for '.$p->name]]);$line=round($price*$qty,2);$subtotal+=$line;$server[]=['product'=>$p,'variant'=>$variant,'label'=>$label,'price'=>$price,'qty'=>$qty,'line'=>$line];}
  $discount=0;$coupon=null;$couponCode=trim((string)($d['coupon_code']??''));if($couponCode){$coupon=Coupon::whereRaw('UPPER(code)=?', [strtoupper($couponCode)])->lockForUpdate()->first();if(!$coupon||!$coupon->is_active||($coupon->starts_at&&$coupon->starts_at->isFuture())||($coupon->expires_at&&$coupon->expires_at->isPast())||($coupon->usage_limit!==null&&$coupon->used_count >= $coupon->usage_limit))throw ValidationException::withMessages(['coupon_code'=>['কুপনটি ব্যবহার করা যাবে না']]);if($subtotal<(float)$coupon->min_order)throw ValidationException::withMessages(['coupon_code'=>['Minimum order required']]);$discount=$coupon->discount_type==='percent'?round($subtotal*(float)$coupon->discount_value/100,2):min((float)$coupon->discount_value,$subtotal);if($coupon->max_discount!==null)$discount=min($discount,(float)$coupon->max_discount);}
  $shipping=strtolower((string)($d['shipping_method']??'dhaka'));$delivery=$shipping==='dhaka'?60:120;$total=max(0,$subtotal-min($discount,$subtotal)+$delivery);$order=Order::create(['order_number'=>$d['order_number']??'FB-'.strtoupper(substr(bin2hex(random_bytes(5)),0,10)),'user_id'=>$user?->id,'customer_name'=>trim($d['customer_name']),'customer_phone'=>trim($d['customer_phone']),'customer_email'=>$d['customer_email']??null,'address'=>trim($d['address']),'order_note'=>$d['order_note']??null,'division'=>$d['division']??null,'district'=>$d['district']??null,'upazila'=>$d['upazila']??null,'delivery_note'=>$d['delivery_note']??null,'shipping_method'=>$shipping,'delivery_area'=>$shipping==='dhaka'?'ঢাকার ভিতরে':'ঢাকার বাইরে','subtotal'=>$subtotal,'delivery_charge'=>$delivery,'discount_amount'=>$discount,'total_amount'=>$total,'payment_method'=>($d['payment_method']??'cod')==='cash'?'cod':$d['payment_method'],'payment_status'=>'pending','payment_title'=>$d['payment_title']??null,'sender_phone'=>$d['sender_phone']??null,'trx_id'=>$d['trx_id']??null,'coupon_code'=>$couponCode?:null,'status'=>'pending']);foreach($server as $x){if($x['variant'])$x['variant']->decrement('stock_quantity',$x['qty']);else$x['product']->decrement('stock_quantity',$x['qty']);$x['product']->increment('sold_quantity',$x['qty']);OrderItem::create(['order_id'=>$order->id,'product_id'=>$x['product']->id,'variant_id'=>$x['variant']?->id,'product_name'=>$x['product']->name,'variant_label'=>$x['label'],'weight_grams'=>$x['variant']?->weight_grams,'unit_price'=>$x['price'],'quantity'=>$x['qty'],'line_total'=>$x['line']]);}if($coupon){$coupon->increment('used_count');CouponUsage::create(['coupon_id'=>$coupon->id,'user_id'=>$user?->id,'order_id'=>$order->id]);}return ['order_id'=>$order->id,'order_number'=>$order->order_number,'subtotal'=>(float)$subtotal,'discount_amount'=>(float)$discount,'delivery_charge'=>(float)$delivery,'total_amount'=>(float)$total];}); }
}
